public static void check(Solution solution) {
    assert Arrays.equals(solution.similarPairs(new int[]{"aabbcc","abc","ab","a","b","c"}), 1);
    assert Arrays.equals(solution.similarPairs(new int[]{"aaa","bbb","ccc","aab","aba","baa"}), 3);
    assert Arrays.equals(solution.similarPairs(new int[]{"aabbcc","abc","aabb","aaabbbcc","abcabc"}), 6);
    assert Arrays.equals(solution.similarPairs(new int[]{"a","b","c","d","e"}), 0);
    assert Arrays.equals(solution.similarPairs(new int[]{"aaa","bbb","ccc","abc","abc"}), 1);
    assert Arrays.equals(solution.similarPairs(new int[]{"abcd","bcad","cabd","dabc"}), 6);
    assert Arrays.equals(solution.similarPairs(new int[]{"nba","cba","dba"}), 0);
    assert Arrays.equals(solution.similarPairs(new int[]{"abc","acb","bac","bca","cab","cba"}), 15);
    assert Arrays.equals(solution.similarPairs(new int[]{"abcd","dcba","abdc","badc"}), 6);
    assert Arrays.equals(solution.similarPairs(new int[]{"aabb","ab","ba"}), 3);
    assert Arrays.equals(solution.similarPairs(new int[]{"abc","def","ghi","jkl"}), 0);
    assert Arrays.equals(solution.similarPairs(new int[]{"aa","bb","cc","abc","cba","bca"}), 3);
    assert Arrays.equals(solution.similarPairs(new int[]{"a","b","c","d"}), 0);
    assert Arrays.equals(solution.similarPairs(new int[]{"a","b","c","d","e","f","g","h","i","j"}), 0);
    assert Arrays.equals(solution.similarPairs(new int[]{"abc","abc","abc","abc"}), 6);
    assert Arrays.equals(solution.similarPairs(new int[]{"abcd","dcba","abcd","dcba","abcd"}), 10);
    assert Arrays.equals(solution.similarPairs(new int[]{"aaa","bbb","ccc","aaa"}), 1);
